using System.Text;
using System.Text.Json;
using Dapper;
using Npgsql;
using Sigov.Application.Agro;
using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Agro;

public sealed class AgroService(NpgsqlConnectionFactory factory,Microsoft.Extensions.Logging.ILogger<AgroService> logger):IAgroService
{
 public async Task<AgroDashboard> DashboardAsync(long t,long e,AgroFiltro f,CancellationToken ct){await using var c=factory.CreateConnection();var a=A(t,e,f);const string sql="""select (select count(*) from sigov.agro_produtor where tenant_id=@T and entidade_id=@E and ativo and not is_deleted and (@Comunidade is null or comunidade=@Comunidade) and (@Status is null or situacao=@Status)) ProdutoresAtivos,(select count(*) from sigov.agro_propriedade where tenant_id=@T and entidade_id=@E and not is_deleted and (@Comunidade is null or comunidade=@Comunidade)) Propriedades,(select coalesce(sum(area_total),0) from sigov.agro_propriedade where tenant_id=@T and entidade_id=@E and not is_deleted and (@Comunidade is null or comunidade=@Comunidade)) AreaTotal,(select count(*) from sigov.agro_visita_tecnica where tenant_id=@T and entidade_id=@E and not is_deleted and (@Inicio is null or data_visita>=@Inicio) and (@Fim is null or data_visita<=@Fim)) VisitasTecnicas,(select count(*) from sigov.agro_programa where tenant_id=@T and entidade_id=@E and status='ATIVO' and not is_deleted) ProgramasAtivos,(select count(*) from sigov.agro_programa_beneficiario b join sigov.agro_programa p on p.id=b.programa_id where b.tenant_id=@T and b.entidade_id=@E and not b.is_deleted and (@Programa is null or p.nome=@Programa)) Beneficiarios,(select coalesce(sum(quantidade),0) from sigov.agro_distribuicao_insumo where tenant_id=@T and entidade_id=@E and not is_deleted and (@Inicio is null or distribuido_em>=@Inicio) and (@Fim is null or distribuido_em<=@Fim)) InsumosDistribuidos,(select count(*) from sigov.agro_servico_maquina where tenant_id=@T and entidade_id=@E and not is_deleted and (@Status is null or status=@Status)) ServicosPatrulha,(select count(*) from sigov.agro_solicitacao where tenant_id=@T and entidade_id=@E and status<>'CONCLUIDA' and not is_deleted) SolicitacoesAbertas,(select count(*) from sigov.agro_solicitacao where tenant_id=@T and entidade_id=@E and status='CONCLUIDA' and not is_deleted) SolicitacoesConcluidas""";return await c.QuerySingleAsync<AgroDashboard>(new CommandDefinition(sql,a,cancellationToken:ct));}
 public async Task<AgroPagina> ListarAsync(long t,long e,string recurso,AgroFiltro f,CancellationToken ct){var m=Map(recurso);var page=Math.Max(1,f.Pagina);var size=Math.Clamp(f.TamanhoPagina,1,100);var a=new{T=t,E=e,B=N(f.Busca),S=N(f.Status),O=(page-1)*size,L=size};var where=$"tenant_id=@T and entidade_id=@E and not is_deleted and (@B is null or {m.Search} ilike '%'||@B||'%') and (@S is null or {m.Status}=@S)";await using var c=factory.CreateConnection();var total=await c.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.{m.Table} where {where}",a,cancellationToken:ct));var rows=(await c.QueryAsync<AgroRegistro>(new CommandDefinition($"select id,{m.Title} Titulo,{m.Subtitle} Subtitulo,{m.Status} Status,created_at CriadoEm from sigov.{m.Table} where {where} order by created_at desc limit @L offset @O",a,cancellationToken:ct))).AsList();return new(rows,page,size,total);}
 public async Task<long> CriarProdutorAsync(long t,long e,long u,string corr,ProdutorInput i,CancellationToken ct){var doc=new string((i.CpfCnpj??"").Where(char.IsDigit).ToArray());if(i.TipoPessoa is not("PF" or "PJ")||(i.TipoPessoa=="PF"&&doc.Length!=11)||(i.TipoPessoa=="PJ"&&doc.Length!=14))throw new ArgumentException("Tipo de pessoa e CPF/CNPJ válido são obrigatórios.");if(string.IsNullOrWhiteSpace(i.NomeRazaoSocial))throw new ArgumentException("Nome/razão social é obrigatório.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_produtor(tenant_id,entidade_id,tipo_pessoa,nome_razao_social,cpf_cnpj,telefone,email,endereco,comunidade,localidade,caf_pronaf,situacao,observacoes,ativo,created_by,updated_by) values(@T,@E,@TipoPessoa,@NomeRazaoSocial,@Doc,@Telefone,@Email,@Endereco,@Comunidade,@Localidade,@CafPronaf,@Situacao,@Observacoes,@Ativo,@U,@U) returning id",new{T=t,E=e,U=u,i.TipoPessoa,NomeRazaoSocial=i.NomeRazaoSocial.Trim(),Doc=doc,i.Telefone,i.Email,i.Endereco,i.Comunidade,i.Localidade,i.CafPronaf,i.Situacao,i.Observacoes,i.Ativo},tx,cancellationToken:ct));await Audit(c,tx,t,e,"PRODUTOR",id,"CRIAR",i,u,corr,ct);await tx.CommitAsync(ct);return id;}catch(PostgresException x)when(x.SqlState==PostgresErrorCodes.UniqueViolation){throw new InvalidOperationException("CPF/CNPJ já cadastrado nesta entidade.",x);}}
 public async Task<long> CriarPropriedadeAsync(long t,long e,long u,string corr,PropriedadeInput i,CancellationToken ct){if(string.IsNullOrWhiteSpace(i.Nome)||i.AreaTotal<0||i.AreaProdutiva<0||i.AreaProdutiva>i.AreaTotal)throw new ArgumentException("Nome e áreas válidas são obrigatórios; área produtiva não pode superar a total.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_propriedade(tenant_id,entidade_id,nome,area_total,area_produtiva,localizacao,comunidade,latitude,longitude,car,itr,ccir,situacao,observacoes,ativo,created_by,updated_by) values(@T,@E,@Nome,@AreaTotal,@AreaProdutiva,@Localizacao,@Comunidade,@Latitude,@Longitude,@Car,@Itr,@Ccir,@Situacao,@Observacoes,@Ativo,@U,@U) returning id",new{T=t,E=e,U=u,i.Nome,i.AreaTotal,i.AreaProdutiva,i.Localizacao,i.Comunidade,i.Latitude,i.Longitude,i.Car,i.Itr,i.Ccir,i.Situacao,i.Observacoes,i.Ativo},tx,cancellationToken:ct));foreach(var p in i.ProdutorIds?.Distinct()??[])await c.ExecuteAsync(new CommandDefinition("insert into sigov.agro_propriedade_produtor(tenant_id,entidade_id,propriedade_id,produtor_id,principal,created_by,updated_by) select @T,@E,@Id,@P,false,@U,@U where exists(select 1 from sigov.agro_produtor where id=@P and tenant_id=@T and entidade_id=@E and not is_deleted)",new{T=t,E=e,Id=id,P=p,U=u},tx,cancellationToken:ct));await Audit(c,tx,t,e,"PROPRIEDADE",id,"CRIAR",i,u,corr,ct);await tx.CommitAsync(ct);return id;}
 public async Task<long> CriarAsync(long t,long e,long u,string corr,string recurso,AgroOperacaoInput i,CancellationToken ct){var m=Map(recurso);if(string.IsNullOrWhiteSpace(i.Titulo))throw new ArgumentException("O campo principal é obrigatório.");if(i.Status is "INDEFERIDO" or "CANCELADO" && string.IsNullOrWhiteSpace(i.Justificativa))throw new ArgumentException("Justificativa é obrigatória para indeferimento/cancelamento.");var (cols,vals)=recurso.ToLowerInvariant() switch{"atividades"=>("propriedade_id,tipo,descricao,status","@PropriedadeId,'ECONOMICA',@Titulo,@Status"),"assistenciatecnica"=>("produtor_id,propriedade_id,data_visita,finalidade,status","@ProdutorId,@PropriedadeId,@Data,@Titulo,@Status"),"programas"=>("nome,tipo,descricao,inicio,fim,status","@Titulo,'APOIO',@Descricao,@Data,@DataFim,@Status"),"insumos"=>("codigo,descricao,unidade,saldo","@Titulo,@Descricao,'UN',coalesce(@Quantidade,0)"),"patrulha"=>("produtor_id,propriedade_id,maquina_id,tipo_servico,horas,data_prevista,status","@ProdutorId,@PropriedadeId,@MaquinaId,@Titulo,@Quantidade,@Data,@Status"),"feiras"=>("nome,local,data_inicio,data_fim,status","@Titulo,coalesce(@Descricao,'Não informado'),@Data,@DataFim,@Status"),"agroindustrias"=>("produtor_id,nome,atividade,situacao","@ProdutorId,@Titulo,coalesce(@Descricao,'Não informada'),@Status"),"solicitacoes"=>("produtor_id,propriedade_id,tipo,descricao,status,justificativa","@ProdutorId,@PropriedadeId,@Titulo,coalesce(@Descricao,@Titulo),@Status,@Justificativa"),_=>throw new ArgumentException("Recurso inválido.")};await using var c=factory.CreateConnection();var a=new{T=t,E=e,U=u,i.Titulo,i.Descricao,Status=string.IsNullOrWhiteSpace(i.Status)?"ATIVO":i.Status,i.ProdutorId,i.PropriedadeId,i.ProgramaId,i.MaquinaId,i.Quantidade,Data=i.Data??DateOnly.FromDateTime(DateTime.UtcNow),i.DataFim,i.Justificativa};var id=await c.ExecuteScalarAsync<long>(new CommandDefinition($"insert into sigov.{m.Table}(tenant_id,entidade_id,{cols},created_by,updated_by) values(@T,@E,{vals},@U,@U) returning id",a,cancellationToken:ct));logger.LogInformation("Agro {Recurso} {Id} criado no tenant {Tenant}",recurso,id,t);return id;}
 public async Task ExcluirAsync(long t,long e,long u,string corr,string recurso,long id,CancellationToken ct){var m=Map(recurso);await using var c=factory.CreateConnection();var n=await c.ExecuteAsync(new CommandDefinition($"update sigov.{m.Table} set ativo=false,is_deleted=true,deleted_at=now(),deleted_by=@U,updated_at=now(),updated_by=@U where tenant_id=@T and entidade_id=@E and id=@Id and not is_deleted",new{T=t,E=e,U=u,Id=id},cancellationToken:ct));if(n==0)throw new KeyNotFoundException("Registro não encontrado.");}
 public async Task<byte[]> ExportarAsync(long t,long e,long u,string corr,string tipo,AgroFiltro f,CancellationToken ct){var m=Map(tipo);await using var c=factory.CreateConnection();var rows=await c.QueryAsync(new CommandDefinition($"select id,{m.Title} nome,{m.Subtitle} detalhe,{m.Status} status,created_at from sigov.{m.Table} where tenant_id=@T and entidade_id=@E and not is_deleted order by id limit 10000",new{T=t,E=e},cancellationToken:ct));var sb=new StringBuilder("Id;Nome;Detalhe;Status;Criado em\r\n");foreach(var r in rows)sb.AppendLine(string.Join(';',((IDictionary<string,object>)r).Values.Select(x=>Csv(x?.ToString()))));await c.ExecuteAsync(new CommandDefinition("insert into sigov.agro_auditoria(tenant_id,entidade_id,entidade,operacao,depois,usuario_id,correlation_id) values(@T,@E,'RELATORIO','EXPORTAR',jsonb_build_object('tipo',@Tipo),@U,@Corr)",new{T=t,E=e,Tipo=tipo,U=u,Corr=corr},cancellationToken:ct));return new UTF8Encoding(true).GetBytes(sb.ToString());}
 static object A(long t,long e,AgroFiltro f)=>new{T=t,E=e,Inicio=f.Inicio,Fim=f.Fim,Comunidade=N(f.Comunidade),Programa=N(f.Programa),Status=N(f.Status)};
 static (string Table,string Title,string Subtitle,string Status,string Search) Map(string r)=>r.ToLowerInvariant() switch{"produtores"=>("agro_produtor","nome_razao_social","comunidade","situacao","nome_razao_social"),"propriedades"=>("agro_propriedade","nome","comunidade","situacao","nome"),"atividades"=>("agro_atividade_produtiva","descricao","tipo","status","descricao"),"assistenciatecnica" or "visitas"=>("agro_visita_tecnica","finalidade","coalesce(tecnico_nome,'')","status","finalidade"),"programas"=>("agro_programa","nome","tipo","status","nome"),"insumos"=>("agro_insumo","descricao","codigo","case when ativo then 'ATIVO' else 'INATIVO' end","descricao"),"distribuicoes"=>("agro_distribuicao_insumo","insumo_id::text","quantidade::text","case when ativo then 'DISTRIBUIDO' else 'INATIVO' end","insumo_id::text"),"patrulha" or "servicos"=>("agro_servico_maquina","tipo_servico","coalesce(horas::text,'')","status","tipo_servico"),"feiras"=>("agro_feira","nome","local","status","nome"),"agroindustrias"=>("agro_agroindustria","nome","atividade","situacao","nome"),"solicitacoes"=>("agro_solicitacao","tipo","left(descricao,120)","status","descricao"),"auditoria"=>("agro_auditoria","operacao","entidade","operacao","entidade"),_=>throw new ArgumentException("Recurso Agro inválido.")};
 static Task Audit(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,string ent,long id,string op,object data,long u,string corr,CancellationToken ct)=>c.ExecuteAsync(new CommandDefinition("insert into sigov.agro_auditoria(tenant_id,entidade_id,entidade,registro_id,operacao,depois,usuario_id,correlation_id) values(@T,@E,@Ent,@Id,@Op,cast(@Data as jsonb),@U,@Corr)",new{T=t,E=e,Ent=ent,Id=id,Op=op,Data=JsonSerializer.Serialize(data),U=u,Corr=corr},tx,cancellationToken:ct));
 static string? N(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();static string Csv(string? x){x??="";if(x.Length>0&&"=+-@".Contains(x[0]))x="'"+x;return '"'+x.Replace("\"","\"\"")+'"';}
}
